// Only the title printed by the loop template is shortened, not menus, breadcrumbs etc.
function perfectpixel_shorten_loop_title_on() {
	add_filter( 'the_title', 'perfectpixel_shorten_loop_title', 99 );
}

function perfectpixel_shorten_loop_title_off() {
	remove_filter( 'the_title', 'perfectpixel_shorten_loop_title', 99 );
}

function perfectpixel_shorten_loop_title( $title ) {
	$max = max( 5, (int) '{{loop_title_max_chars}}' );
	return mb_strlen( $title ) > $max ? rtrim( mb_substr( $title, 0, $max - 1 ) ) . 'β€¦' : $title;
}
